-- Tables for the sign-up pipeline. Do not edit this file.
-- The tests run it inside a schema of their own and drop that schema when they finish.

CREATE TABLE staging_signups (
    email        text PRIMARY KEY,
    name         text NOT NULL,
    session      text NOT NULL,
    seats        integer NOT NULL,
    signed_up_at timestamp NOT NULL
);

CREATE TABLE session_summary (
    session text PRIMARY KEY,
    signups integer NOT NULL,
    seats   integer NOT NULL
);
